
"""
Cross-platform setup script for BitBucket QA Suite.
Works on Windows, Linux, and macOS.
RUN THIS SCRIPT FROM THE CLONED REPO DIRECTORY.

Usage:
    python setup_all.py          # Full setup (writes all QA files + installs + tests)
    python setup_all.py --skip-tests   # Skip test validation

Note: This script is self-contained. Place it in the cloned project folder
and run it. All necessary QA files will be created automatically.
"""

import os
import sys
import subprocess
import shutil
import base64
import argparse
from pathlib import Path


class Colors:
    GREEN = '\033[92m'
    RED = '\033[91m'
    YELLOW = '\033[93m'
    CYAN = '\033[96m'
    BOLD = '\033[1m'
    END = '\033[0m'

    @staticmethod
    def disable():
        Colors.GREEN = Colors.RED = Colors.YELLOW = Colors.CYAN = Colors.BOLD = Colors.END = ''


def print_header(text):
    print(f"\n{Colors.BOLD}{Colors.CYAN}{'=' * 50}")
    print(f"  {text}")
    print(f"{'=' * 50}{Colors.END}\n")


def print_step(step, total, text):
    print(f"{Colors.BOLD}[{step}/{total}]{Colors.END} {text}")


def print_ok(text):
    print(f"  {Colors.GREEN}OK{Colors.END} {text}")


def print_error(text):
    print(f"  {Colors.RED}ERROR{Colors.END} {text}")


def run_command(cmd, cwd=None, check=True):
    try:
        result = subprocess.run(
            cmd, cwd=cwd, capture_output=True, text=True, timeout=300
        )
        if check and result.returncode != 0:
            stderr = result.stderr.strip()[:200]
            print(f"  {Colors.RED}FAILED{Colors.END}: {stderr}")
            return False
        return True
    except subprocess.TimeoutExpired:
        print(f"  {Colors.RED}TIMEOUT{Colors.END}: Command took too long")
        return False
    except FileNotFoundError:
        print(f"  {Colors.RED}NOT FOUND{Colors.END}: {cmd[0]}")
        return False
    except Exception as e:
        print(f"  {Colors.RED}ERROR{Colors.END}: {e}")
        return False


def get_python_command():
    if sys.platform == 'win32':
        candidates = ['python', 'python3']
    else:
        candidates = ['python3', 'python']

    for cmd in candidates:
        try:
            result = subprocess.run(
                [cmd, '--version'], capture_output=True, text=True, timeout=10
            )
            if result.returncode == 0:
                version_str = result.stdout.strip()
                parts = version_str.split('.')
                if len(parts) >= 2:
                    major = int(parts[0].replace('Python ', ''))
                    minor = int(parts[1])
                    if major >= 3 and minor >= 11:
                        return cmd
                    else:
                        print(f"  {Colors.YELLOW}WARNING{Colors.END}: Found {version_str}, need 3.11+")
        except (FileNotFoundError, ValueError):
            continue
    return None


def get_venv_python(project_dir):
    if sys.platform == 'win32':
        return str(project_dir / 'venv' / 'Scripts' / 'python.exe')
    else:
        return str(project_dir / 'venv' / 'bin' / 'python')


def write_qa_files(project_dir):
    """Write all embedded QA files to the project directory."""
    count = 0

    for relpath, b64_data in EMBEDDED_FILES.items():
        if not b64_data:
            continue
        filepath = project_dir / QA_DIR / relpath
        filepath.parent.mkdir(parents=True, exist_ok=True)
        try:
            content = base64.b64decode(b64_data)
            filepath.write_bytes(content)
            if relpath.startswith('.git/hooks/') and sys.platform != 'win32':
                filepath.chmod(0o755)
            count += 1
        except Exception as e:
            print("  WARN: Could not write " + relpath + ": " + str(e))

    if count > 0:
        print_ok("Written " + str(count) + " QA files")
    else:
        print_ok("All QA files already present")


def install_git_hooks(project_dir):
    """Install the QA gate hooks into the REAL git hooks dir.

    bitbucket-qa/.git/hooks/ is only a bundled copy; git only runs hooks from
    <repo>/.git/hooks/. This resolves the actual repo root and copies the right
    variant (.bat on Windows, shell otherwise) so gates run on commit/push.
    """
    try:
        result = subprocess.run(
            ["git", "-C", str(project_dir), "rev-parse", "--show-toplevel"],
            capture_output=True, text=True, timeout=10
        )
    except FileNotFoundError:
        print("  WARN: git not found - skipping git hook install.")
        return
    if result.returncode != 0:
        print("  WARN: project is not a git repo - skipping git hook install.")
        return

    git_root = Path(result.stdout.strip())
    target = git_root / ".git" / "hooks"
    target.mkdir(parents=True, exist_ok=True)

    suffix = ".bat" if sys.platform == 'win32' else ""
    installed = 0
    for name in ("pre-push", "pre-commit"):
        src = project_dir / QA_DIR / ".git" / "hooks" / (name + suffix)
        if not src.exists():
            print("  WARN: hook source not found: " + str(src))
            continue
        dst = target / name
        try:
            dst.write_bytes(src.read_bytes())
            if suffix == "":
                dst.chmod(0o755)
            installed += 1
            print_ok("Installed hook: " + name)
        except Exception as e:
            print("  WARN: could not install " + name + ": " + str(e))

    if installed:
        print_ok("Git hooks installed to " + str(target))
    else:
        print("  No git hooks were installed.")


QA_DIR = "bitbucket-qa"

EMBEDDED_FILES = {
    "requirements.txt": "",
    "requirements.lock": "",
    ".gitignore": "",
    "code_scanner.py": "",
    "test_precheck.py": "",
    "tests/__init__.py": "IyBRQSB0ZXN0IHBhY2thZ2UK",
    "tests/test_sample.py": "",
    "tests/test_fixes.py": "",
    "tests/test_quality_gate.py": "",
    "tests/test_scanner_exit.py": "",
    "tests/test_tools_units.py": "",
    "dependency_health.py": "",
    "performance_benchmark.py": "",
    "pipeline_dashboard.py": "",
    "smart_test_selector.py": "",
    "run_full_pipeline.bat": "",
    "run_full_pipeline.sh": "",
    "bitbucket-pipelines.yml": "",
    ".git/hooks/pre-push": "",
    ".git/hooks/pre-push.bat": "",
    ".git/hooks/pre-commit": "",
    ".git/hooks/pre-commit.bat": "",
}


def setup(skip_tests=False):
    try:
        import venv  # noqa: F401
    except ImportError:
        print_error("venv module not found. Install with: pip install virtualenv")
        return False

    project_dir = Path(__file__).parent.resolve()
    total_steps = 5

    print_header("BitBucket QA Suite - One-Click Setup")
    print("  Platform: " + sys.platform)
    print("  Python:   " + sys.version)
    print("  Directory: " + str(project_dir) + "\n")

    # Step 0: Write QA files
    print_step(1, total_steps, "Writing QA files...")
    write_qa_files(project_dir)
    install_git_hooks(project_dir)

    # Step 1: Check Python
    print_step(2, total_steps, "Checking Python...")
    python_cmd = get_python_command()
    if not python_cmd:
        print_error("Python 3.11+ not found!")
        print("  Please install Python 3.11 or newer:")
        print("  https://www.python.org/downloads/")
        return False
    print_ok("Found " + python_cmd)

    # Step 2: Create virtual environment
    print_step(3, total_steps, "Setting up virtual environment...")
    venv_dir = project_dir / 'venv'
    venv_python = get_venv_python(project_dir)

    venv_usable = False
    if venv_dir.exists() and Path(venv_python).exists():
        pip_check = subprocess.run(
            [venv_python, '-m', 'pip', '--version'],
            capture_output=True, text=True, timeout=10
        )
        venv_usable = pip_check.returncode == 0

        if not venv_usable:
            print("  Venv exists but pip is missing, recovering via ensurepip...")
            ensure_result = subprocess.run(
                [venv_python, '-m', 'ensurepip', '--upgrade'],
                capture_output=True, text=True, timeout=60
            )
            if ensure_result.returncode == 0:
                venv_usable = True
                print("  Pip recovered successfully")

    if venv_usable:
        print("  Existing venv found, reusing...")
    else:
        if venv_dir.exists():
            print("  Removing broken venv...")
            try:
                shutil.rmtree(venv_dir)
            except PermissionError:
                print_error("Cannot delete locked venv. Close all other Python processes and try again.")
                return False

        result = subprocess.run(
            [python_cmd, '-m', 'venv', str(venv_dir)],
            capture_output=True, text=True, timeout=120
        )
        if result.returncode != 0:
            print_error("Failed to create venv: " + str(result.stderr))
            return False

        pip_check = subprocess.run(
            [venv_python, '-m', 'pip', '--version'],
            capture_output=True, text=True, timeout=10
        )
        if pip_check.returncode != 0:
            print_error("Venv created but pip is missing!")
            return False

    print_ok("Virtual environment ready")

    # Step 3: Install dependencies
    print_step(4, total_steps, "Installing dependencies...")
    pip_cmd = [venv_python, '-m', 'pip']

    if not run_command(pip_cmd + ['install', '--upgrade', 'pip'], cwd=str(project_dir)):
        print_error("Failed to upgrade pip")
        return False

    if not run_command(pip_cmd + ['install', '-r', 'requirements.txt'], cwd=str(project_dir)):
        print_error("Failed to install dependencies")
        return False
    print_ok("All dependencies installed")

    # Step 4: Validate
    if skip_tests:
        print_step(5, total_steps, "Skipping validation (--skip-tests)")
    else:
        print_step(5, total_steps, "Running validation tests...")
        test_result = subprocess.run(
            [venv_python, '-m', 'pytest', 'test_precheck.py', 'tests/', '-v', '--tb=short'],
            cwd=str(project_dir), timeout=120
        )
        if test_result.returncode != 0:
            print_error("Some tests failed! Check output above.")
            return False

        print("\n  Verifying tools...")
        tools = [
            ("dependency_health", "from dependency_health import DependencyHealthCheck; c = DependencyHealthCheck(); pkgs = c._parse_requirements(); print('  dependency_health: OK (' + str(len(pkgs)) + ' packages)')"),
            ("pipeline_dashboard", "from pipeline_dashboard import PipelineDashboard; d = PipelineDashboard(); print('  pipeline_dashboard: OK')"),
            ("performance_benchmark", "from performance_benchmark import PerformanceBenchmark; b = PerformanceBenchmark(); print('  performance_benchmark: OK')"),
            ("smart_test_selector", "from smart_test_selector import SmartTestSelector; print('  smart_test_selector: OK')"),
        ]
        all_ok = True
        qa_dir = project_dir / QA_DIR
        for name, code in tools:
            result = subprocess.run(
                [venv_python, '-c', code],
                cwd=str(qa_dir), capture_output=True, text=True, timeout=30
            )
            if result.returncode == 0:
                print_ok(result.stdout.strip())
            else:
                print_error(name + ": " + result.stderr.strip()[:100])
                all_ok = False

        if not all_ok:
            print_error("Some tools failed verification!")
            return False

    print_header("Setup Complete!")
    print("  Available commands:")
    print("    pytest test_precheck.py -v        Run precheck tests")
    print("    pytest tests/ -v                  Run all tests")
    print("    python smart_test_selector.py     Smart test selection")
    print("    python performance_benchmark.py   Run benchmarks")
    print("    python dependency_health.py       Check dependencies")
    print("    python pipeline_dashboard.py      Generate dashboard")
    print()
    return True


def main():
    if sys.platform == 'win32':
        os.system('')
        try:
            import ctypes
            kernel32 = ctypes.windll.kernel32
            kernel32.SetConsoleMode(kernel32.GetStdHandle(-11), 7)
        except Exception:
            Colors.disable()

    parser = argparse.ArgumentParser(description="BitBucket QA Suite - Cross-platform Setup")
    parser.add_argument("--skip-tests", action="store_true", help="Skip test validation after setup")
    args = parser.parse_args()

    success = setup(skip_tests=args.skip_tests)
    sys.exit(0 if success else 1)


if __name__ == "__main__":
    main()

